-- BattleTech planetary systems, Era 3052
-- Based on the user-uploaded SUCKit-derived SQL file.
-- image and sizeable_economy are heuristic guesses from planet names;
-- random fallback choices are deterministic for repeatable exports.

CREATE TABLE IF NOT EXISTS planets (
    planet VARCHAR(100) PRIMARY KEY,
    x DOUBLE NOT NULL,
    y DOUBLE NOT NULL,
    controller VARCHAR(255),
    image VARCHAR(50) NOT NULL CHECK (image IN ('blue.png', 'dark.png', 'desert.png', 'earth.png', 'forest.png', 'gas.png', 'lava.png', 'red.png')),
    sizeable_economy BOOLEAN DEFAULT FALSE NOT NULL
);

